estado:
cat > /home/learner/aso/f31/estado.sh <<'SOLUCION'
#!/bin/bash
[ $# -eq 1 ] || { echo 'uso: estado.sh PID' >&2; exit 1; }
[[ $1 =~ ^[0-9]+$ ]] || { echo 'error: el PID debe ser un número' >&2; exit 2; }
datos=$(ps -o pid=,ppid=,stat=,comm= -p "$1") || { echo "error: no existe el proceso $1" >&2; exit 3; }
read -r pid ppid stat comm <<< "$datos"
echo "PID=$pid PPID=$ppid ESTADO=$stat ORDEN=$comm"
SOLUCION
chmod 755 /home/learner/aso/f31/estado.sh
chown learner:learner /home/learner/aso/f31/estado.sh

nohup:
bgl() { runuser -u learner -- setsid -f "$@" >/dev/null 2>&1 </dev/null; }
bgl nohup sleep 3301
sleep 0.5

disown:
bgl() { runuser -u learner -- setsid -f "$@" >/dev/null 2>&1 </dev/null; }
bgl sleep 3302
sleep 0.5
